mapper.select:
SELECT ro.id AS orderId,ro.order_no AS orderNo,ro.status,
  su.id AS studentUid,su.real_name AS studentName,
  ft.id AS faultTypeId,ft.type_name AS faultTypeName,
  ro.campus_id AS campusId,campus.area_name AS campusName,
  ro.area_id AS areaId,area.area_name AS areaName,
  ro.building_id AS buildingId,building.area_name AS buildingName,
  ro.room_id AS roomId,room.area_name AS roomName,
  CONCAT_WS(' / ',campus.area_name,area.area_name,building.area_name,room.area_name,ro.location_detail) AS locationText,
  ro.current_assignee_id AS currentAssigneeId,wu.real_name AS workerName,
  ro.report_time AS reportTime,ro.accept_deadline AS acceptDeadline,
  ro.complete_deadline AS completeDeadline,ro.complete_time AS completeTime,
  ro.exception_flag AS exceptionFlag,ro.duplicate_flag AS duplicateFlag
FROM repair_order ro
LEFT JOIN sys_user su ON su.id=ro.student_uid AND su.deleted=0
LEFT JOIN repair_fault_type ft ON ft.id=ro.fault_type_id
LEFT JOIN repair_area campus ON campus.id=ro.campus_id AND campus.deleted=0
LEFT JOIN repair_area area ON area.id=ro.area_id AND area.deleted=0
LEFT JOIN repair_area building ON building.id=ro.building_id AND building.deleted=0
LEFT JOIN repair_area room ON room.id=ro.room_id AND room.deleted=0
LEFT JOIN repair_worker rw ON rw.id=ro.current_assignee_id AND rw.deleted=0
LEFT JOIN sys_user wu ON wu.id=rw.user_id AND wu.deleted=0
WHERE ro.deleted=0
AND ro.student_uid=#{studentUid}
AND ro.current_assignee_id=#{currentAssigneeId}
AND ro.order_no LIKE CONCAT('%',#{orderNo},'%')
AND ro.status IN #{s}
AND ro.fault_type_id=#{faultTypeId}
AND ro.campus_id=#{campusId}
AND ro.area_id=#{areaId}
AND ro.building_id=#{buildingId}
AND ro.room_id=#{roomId}
AND ro.current_assignee_id=#{workerId}
AND ro.report_time >=#{reportStartTime}
AND ro.report_time <=#{reportEndTime}
AND ro.exception_flag=1
AND ro.duplicate_flag=1
AND ro.status=1 AND ro.accept_deadline IS NOT NULL AND ro.accept_deadline < #{now}
AND ro.status IN (2,4) AND ro.complete_deadline IS NOT NULL AND ro.complete_deadline < #{now}
ORDER BY ro.report_time DESC,ro.id DESC

mapper.update:
UPDATE repair_order SET status=1,current_assignee_id=#{workerId},dispatch_time=#{dispatchTime},accept_deadline=#{acceptDeadline},accept_time=NULL
WHERE id=#{id} AND deleted=0 AND status=#{expectedStatus}
AND current_assignee_id IS NULLAND current_assignee_id=#{expectedAssigneeId}

UPDATE repair_order SET status=0,current_assignee_id=NULL,dispatch_time=NULL,accept_deadline=NULL,accept_time=NULL
WHERE id=#{id} AND deleted=0 AND status=#{expectedStatus}
AND current_assignee_id IS NULLAND current_assignee_id=#{expectedAssigneeId}

mapper.select:
SELECT id FROM repair_order WHERE deleted=0 AND current_assignee_id=#{assigneeId}
AND status IN #{s}
ORDER BY id
